  "explain": "📖 교재 근거:\n특징: R-COOH로 표시되는 화합물 / 지방을 가수분해하여 얻어지며, 탄소수가 12개 이상 / 천연의 유지와 밀랍 등에 에스테르류로 함유함 / 세정용 계면활성제, 유화제, 분산제, 경도·점도 조절용, 연화제 목적으로 사용함 / 알칼리인 소듐하이드록사이드(NaOH), 포타슘하이드록사이드(KOH), 트라이에탄올아민과 병용하면 비누를 형성\n해설: 고급 지방산은 지방을 가수분해하여 얻어지는 탄소수 12개 이상의 R-COOH 화합물로 라우릭애씨드(①) 등이 이에 해당하며, 글리세린(③)은 고급 지방산에 해당하지 않습니다. 따라서 고급 지방산에 해당하지 않는 정답은 ③번입니다.",
