  "context": "다음 중 화장품 제조 시 점증제(Viscosity Modifier)로 사용되는 천연 유래 고분자 물질이 아닌 것은?",
  "statement": "카보머 (Carbomer)",
  "truth": true,
  "mode": "answer",
  "sid": "manufacturing_st_0a2e4d",
  "derivedFrom": "subject2_q13#1",
  "explain": "📖 교재 근거:\n| 카보머 | Carbomer | 점증제 | 수상층 | 수상층에 용해되어 화장품의 점도를 높이고 제형을 안정화하는 데 도움을 주는 점증 성분입니다. | 0.1~1.0 | - | 점증·안정화 | 중빈도 | pH 조절 필요, 중화 후 젤 형성 | - |\n해설: 카보머는 수상층에서 pH 조절 및 중화를 거쳐 젤을 형성해 점도를 높이고 제형을 안정화하는 점증제 성분으로, 천연 유래 고분자 물질이 아니므로 정답은 ①입니다. 반면 잔탄검을 비롯한 구아검, 젤라틴, 아가(한천) 등은 화장품 제조 시 점증제로 사용되는 천연 유래 고분자 물질에 해당하므로 오답입니다.",
