  "explain": "📖 교재 근거:\n| 세라마이드 | Ceramide | 기능성 성분 | 유상층 | 피부 장벽을 구성하는 주요 성분으로, 보습과 피부 유연성 유지에 도움을 주는 성분입니다. | 0.1~1.0 | - | 보습, 탄력, 민감성 | 고빈도 | 세포간지질 성분, 피부장벽 기능 회복 | - |\n해설: 정답인 ② 스쿠알란은 각질세포간 지질의 3대 구성 성분에 속하지 않습니다. 반면 오답인 ① 세라마이드는 제시된 근거에 명시되어 있듯이 피부 장벽을 구성하고 피부장벽 기능 회복에 기여하는 세포간 지질 성분에 해당합니다.",
