  "derivedFrom": "subject2_q29#1",
  "explain": "📖 교재 근거:\n> 원료 검사 → 계량 → 원료 투입(예비 혼합기) → 필터(매쉬, mesh) → 유화 → 냉각 → 숙성조 → 검사 → 충전 → 포장\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 원료 계량 구역의 위생 관리 방법으로 적합하지 않은 것은 ②번입니다. 계량이 완료된 원료 용기를 밀폐하지 않고 공기가 통하도록 열어두면 오염의 원인이 될 수 있으므로, 용기를 열어둔다고 설명한 ②번은 옳지 않습니다.",
