  "mode": "answer",
  "sid": "manufacturing_st_2b402a",
  "derivedFrom": "subject2_q33#1",
  "explain": "📖 교재 근거:\nSPF = (제품을 바른 피부의 최소 홍반량(MED) / 제품을 바르지 않은 피부의 최소 홍반량(MED))\n해설: SPF(Sun Protection Factor)는 자외선 B(UVB)를 차단하는 지수로, 제품을 바른 피부의 최소홍반량과 바르지 않은 피부의 최소홍반량의 비율을 나타내므로 ②번이 정답입니다. 반면 자외선 A(UVA) 차단 효과를 나타내는 것은 자외선A 차단등급(PA)이므로 ①번은 옳지 않습니다.",
