  "context": "다음 중 위해성 등급이 '가등급'인 위해화장품의 회수 실시기간은 회수를 시작한 날부터 며칠 이내인가?",
  "statement": "3일 이내",
  "truth": false,
  "mode": "answer",
  "sid": "manufacturing_st_51938f",
  "derivedFrom": "subject2_q34#1",
  "explain": "📖 교재 근거:\n| 회수 계획 | • 해당 화장품에 대해 즉시 판매 중지 등 필요 조치<br>• 회수 대상 화장품이라는 사실을 안 날부터 5일 이내 아래 서류와 함께 회수계획서를 지방식품의약품안전청장에게 제출(다만, 제출기한까지 회수계획서의 제출이 곤란하다고 판단되는 경우에는 그 사유를 밝히고 제출기한 연장을 요청해야 함)<br>  - 해당 품목의 제조·수입기록서 사본<br>  - 판매처별 판매량·판매일 등의 기록<br>  - 회수 사유를 적은 서류 |\n해설: 위해성 등급이 '가등급'인 위해화장품의 회수 실시기간은 회수를 시작한 날부터 15일 이내이므로 정답은 ②입니다. 따라서 3일, 7일, 30일, 60일 이내로 제시된 ①, ③, ④, ⑤는 옳지 않습니다.",
