  "explain": "📖 법령 근거 (L336):\n③ 완제품의 보관용 검체는 적절한 보관조건 하에 지정된 구역 내에서 제조단위별로 사용기한까지 보관하여야\n한다. 다만, 개봉 후 사용기간을 기재하는 경우에는 제조일로부터 3년간 보관하여야 한다.\n해설: 근거 규정에 따르면 개봉 후 사용기간을 기재하는 경우 제조일로부터 3년간 보관하여야 하므로 정답은 ③입니다. 따라서 1년, 2년, 5년, 10년으로 제시된 선지(①, ②, ④, ⑤)는 해당 보관 기간과 일치하지 않아 오답입니다.",
