  "context": "계면활성제의 임계 미셀 농도(CMC, Critical Micelle Concentration)에 관한 설명",
  "statement": "CMC 이상의 농도에서 계면활성제 분자들이 스스로 회합하여 미셀(Micelle)을 형성하기 시작한다.",
  "truth": true,
  "mode": "fact",
  "sid": "manufacturing_st_385ad5",
  "derivedFrom": "subject2_q40#1",
  "explain": "📖 교재 근거:\n수용액 내에 계면활성제의 농도가 증가하면 분자 간 집합체인 미셀을 형성한다. 미셀이 형성될 때 계면활성제의 농도를 임계미셀농도(CMC: Critical Micelle Concentration)라고 한다.\n해설: 임계 미셀 농도(CMC)는 수용액 내 계면활성제의 농도가 증가하여 분자 간 집합체인 미셀을 형성할 때의 농도를 의미합니다. 따라서 CMC 이상이 되었을 때 용액의 전기전도도가 급격하게 수직 상승한다는 ⑤번 설명은 옳지 않은 설명으로 정답입니다.",
