  "truth": false,
  "mode": "answer",
  "sid": "manufacturing_st_7f729a",
  "derivedFrom": "subject2_q41#1",
  "explain": "📖 교재 근거:\n| 합일(coalescence) | 분산된 입자가 서로 결합하여 보다 큰 입자 상태로 되는 것으로 유화 파괴의 전단계로 판단될 수 있음. 합일 현상이 계속되면 수상과 유상이 완전이 분리되는 상분리(phase separation)이 발생 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 비이온 계면활성제 수용액의 온도를 높일 때 용액이 흐려지면서 상분리가 일어나는 온도를 가리키는 용어는 ④ '曇點 (Cloud Point, 흐림점)'입니다. 따라서 이와 관련이 없는 임계온도, 융점, 유리전이온도, 발화점을 제시한 ①, ②, ③, ⑤는 오답입니다.",
