  "context": "다음 중 유지(기름)의 화학적 특성을 평가하는 지표 중 '1g의 유지를 검화(비누화)하는 데 필요한 수산화칼륨(KOH)의 밀리그램(mg) 수'를 뜻하는 용어는?",
  "statement": "산가 (Acid Value)",
  "truth": false,
