  "explain": "📖 교재 근거 (기능성화장품 심사에 관한 규정):\n(나) Draize 법 (Jordan modification)\n해설: 1g의 유지를 검화(비누화)하는 데 필요한 수산화칼륨(KOH)의 밀리그램(mg) 수를 뜻하는 용어는 비누화가(Saponification Value)이므로 ③이 정답입니다. 따라서 산가, 요오드가, 하이드록실가, 에스테르가는 문제의 정의와 부합하지 않아 오답입니다.",
