  "explain": "📖 교재 근거 (restricted_ingredients):\n| 징크피리치온 | Zinc Pyrithione | 기타 | - | 화장품의 변질을 방지하는 방부 및 보존제로 사용되며, 사용에 제한이 있는 성분입니다. | - | 비듬 및 가려움을 덜어주고 씻어내는 제품(샴푸, 린스) 및 탈모 증상의 완화에 도움을 주는 화장품에 총 징크피리치온으로서 1.0% | 특수 제한 | 중빈도 | 기타 제품에는 사용금지 | - |\n해설: 정답인 1,2-헥산디올은 화장품에서 방부제 대체 성분으로 널리 쓰이며 보습 효능을 동시에 지닌 다가 알코올계 성분입니다. 반면 선지의 징크피리치온은 변질을 방지하는 방부 및 보존제 등으로 사용되나, 비듬 완화나 탈모 증상 완화 제품 등에 배합 한도가 정해진 사용 제한 원료이므로 해당하지 않습니다.",
