  "explain": "📖 교재 근거:\n| 비타민C(아스코르브산) | Vitamin C (Ascorbic Acid) | 기능성 성분 | 수상층 | 활성 성분으로 피부에 생기와 활력을 부여하여 맑고 건강한 피부 유지에 도움을 주는 성분입니다. | 0.5~5.0 | - | 미백, 색소침착, 주름 | 고빈도 | 불안정하여 유도체 형태로 사용 | - |\n해설: 비타민 C(Vitamin C)에 해당하는 성분은 아스코빅애씨드(Ascorbic Acid, 아스코르브산)로, 불안정한 특성을 지녀 유도체 형태로도 사용되므로 ④번이 정답입니다. 반면 판테놀(③)은 비타민 B5 전구체로서 보습 및 진정에 사용되는 성분이며, 나머지 선지들 역시 비타민 C에 해당하지 않습니다.",
