  "explain": "📖 교재 근거:\n| 배지 | • 세균용: 대두카제인 소화한천배지<br>• 진균용: 사부로포도당 한천배지 또는 포테이토덱스트로즈한천배지에 배지 100mL당 클로람페니콜 50mg을 넣음 |\n해설: 교재에 따르면 세균용 배지로는 대두카제인소화한천배지(TSA), 진균용 배지로는 사부로포도당한천배지(SDA)가 사용되므로 ①번과 ⑤번은 올바른 매칭입니다. 따라서 배지의 종류와 타깃 미생물의 연결이 올바르지 않은 것은 ②번입니다.",
