  "explain": "📖 교재 근거:\n| 중대한 유해사례 (Serious AE) | 유해사례 중 다음 어느 하나에 해당하는 경우: 사망을 초래하거나 생명을 위협하는 경우 / 입원 또는 입원기간의 연장이 필요한 경우 / 지속적 또는 중대한 불구나 기능 저하를 초래하는 경우 / 선천적 기형 또는 이상을 초래하는 경우 / 기타 의학적으로 중요한 상황 |\n해설: 근거에 따르면 '중대한 유해사례'는 사망이나 생명의 위협(④), 입원 또는 입원 기간의 연장 필요(②), 지속적·중대한 불구나 기능 저하(③), 선천적 기형 또는 이상 초래(⑤) 등에 해당하는 경우를 말합니다. 따라서 '일시적인 경미한 피부 붉어짐이나 단순 가려움증'은 중대한 유해사례의 판단 범주에 해당하지 않으므로 ①번이 정답입니다.",
