  "explain": "📖 교재 근거:\n| 위해화장품의 공표 | • 식품의약품안전처장은 다음 각 호의 어느 하나에 해당하는 경우에는 해당 영업자에 대하여 그 사실의 공표를 명할 수 있음<br>  - 위해화장품 회수에 따른 회수계획을 보고받은 때<br>  - 위해화장품의 공표에 따른 회수계획을 보고받은 때<br>• 식품의약품안전처장은 국민 건강에 대한 위해를 방지하기 위하여 위해가 발생하였거나 발생할 우려가 있는 직접구매 해외화장품에 관한 정보를 공표할 수 있음<br>• 공표의 방법·절차 등에 필요한 사항은 총리령으로 정함<br>• 공표명령을 받은 영업자는 지체 없이 발생 사실 또는 아래 사항을 전국을 보급지역으로 하는 1개 이상의 일반일간신문 및 해당 영업자의 인터넷 홈페이지에 게재해야 함<br>• 식품의약품안전처의 인터넷 홈페이지에 게재...\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 제시된 정답에 따라 CGMP 기준상 미생물 오염을 방지하기 위한 데드 레그(Dead Leg)의 배관 길이 제한으로 가장 적절한 것은 ③번(L < 2D 이하 또는 3D 이하 권장)입니다. 따라서 배관 길이에 제한이 없다고 하거나 기준과 다른 수치를 제시한 ①, ②, ④, ⑤번은 올바르지 않습니다.",
