  "context": "CGMP 기준상 완제품 보관실의 '부적합품' 관리 방법으로 가장 적합한 것은?",
  "statement": "폐기 대기 상태라도 품질 책임자 승인 없이 생산라인에 재투입한다.",
  "truth": false,
  "mode": "fact",
  "sid": "manufacturing_st_2b2741",
  "derivedFrom": "subject2_q91#5",
  "explain": "📖 법령 근거 (L609):\n④ 출고할 제품은 원자재, 부적합품 및 반품된 제품과 구획된 장소에서 보관하여야 한다. 다만 서로 혼동을 일으킬 우려가 없는 시스템에 의하여 보관되는 경우에는 그러하지 아니할 수 있다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 제19조(보관 및 출고)에 따라 출고할 완제품은 부적합품과 구획된 장소에서 보관해야 하므로, 부적합품을 적합 제품과 명확히 격리된 별도 구획 구역에 식별 표시를 하여 보관하는 ④번이 가장 적합합니다. 따라서 적합품과 섞어 보관하거나 품질책임자의 승인 없이 임의로 위장, 출하, 재투입하는 내용의 선지(①, ②, ③, ⑤)는 모두 기준에 부합하지 않습니다.",
