  "explain": "📖 법령 근거 (L198):\n② 원자재의 입고 시 구매 요구서, 원자재 공급업체 성적서 및 현품이 서로 일치하여야 한다. 필요한 경우 운송 관련 자료를 추가적으로 확인할 수 있다.\n해설: CGMP 기준 제11조(입고관리)에 따라 화장품제조업자는 철저한 입고관리를 위해 원자재 공급자를 평가하여 선정하고 관리감독을 수행해야 하므로, 정답은 '③ 공급업체 평가 및 관리'입니다. 반면 재작업 처리, 소비자 불만 처리, 모니터링, 밸리데이션(①, ②, ④, ⑤)은 공급자를 평가·선정하고 관리감독하는 원자재 입고관리 내용에 부합하지 않습니다.",
