  "statement": "25.0% 이하",
  "truth": true,
  "mode": "answer",
  "sid": "manufacturing_st_3d2e41",
  "derivedFrom": "subject2_q104#1",
  "explain": "📖 교재 근거:\n```mermaid\nflowchart LR\nP[\"페녹시에탄올<br/>보존제\"] -->|\"1.0% 이하\"| L1[\"최종 제품\"]\nB[\"벤조익애씨드<br/>보존제\"] -->|\"0.5% 이하\"| L2[\"씻어내지 않는 제품\"]\nS[\"살리실산\"] -->|\"0.5% 이하\"| L3[\"영유아용 사용금지<br/>(씻어내는 제품 제외)\"]\nT[\"티타늄디옥사이드<br/>자외선차단제\"] -->|\"25.0% 이하\"| L4[\"최종 제품\"]\n```\n해설: 무기 자외선 차단 성분인 티타늄디옥사이드의 최대 허용 한도는 25.0% 이하이므로 ①이 정답입니다. 따라서 기준과 다른 수치를 제시한 ②(10.0% 이하), ③(15.0% 이하), ④(20.0% 이하), ⑤(5.0% 이하)는 오답입니다.",
