  "explain": "📖 교재 근거:\n- 유화에 영향을 미치는 요인: 유화제(종류와 사용량), 원료의 성질, 유화 조건(성분 첨가 순서, 교반속도, 온도, 유화장치 등)\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 제시된 내용에서 유화 및 상태에 영향을 미치는 조건으로 온도가 제시되어 있으므로 ④번 '유체의 온도'를 철저히 제어해야 합니다. 반면 대기압, 조도, 실내 소음, 작업자의 혈압(①, ②, ③, ⑤)은 유화 및 점도에 영향을 미치는 요인에 해당하지 않습니다.",
