  "statement": "0.1% 이하",
  "truth": false,
  "mode": "answer",
  "sid": "manufacturing_st_ed3fb8",
  "derivedFrom": "subject2_q108#1",
  "explain": "📖 교재 근거:\n| 벤조익애씨드 | Benzoic Acid | 보존제 | 수상층 | 화장품의 미생물 번식을 억제하여 제품의 안정성을 높이는 최대 0.5% 사용 가능한 방부제 성분입니다. | 0.1~0.5 | 0.5% (기타), 2.5% (씻어내는) | 방부·보존 | 고빈도 | 산으로서 계산, 씻어내는 제품에 2.5% 허용 | - |\n해설: 벤조익애씨드는 사용 후 씻어내는 제품을 제외한 일반 제품에서 산으로서 계산하여 최대 0.5% 이하로 사용 한도가 규정되어 있으므로 정답은 ②입니다. 따라서 0.1% 이하, 0.3% 이하, 1.0% 이하 또는 배합 금지를 제시한 선지 ①, ③, ④, ⑤는 옳지 않습니다.",
