  "explain": "📖 교재 근거:\n| 회수 계획 | • 해당 화장품에 대해 즉시 판매 중지 등 필요 조치<br>• 회수 대상 화장품이라는 사실을 안 날부터 5일 이내 아래 서류와 함께 회수계획서를 지방식품의약품안전청장에게 제출(다만, 제출기한까지 회수계획서의 제출이 곤란하다고 판단되는 경우에는 그 사유를 밝히고 제출기한 연장을 요청해야 함)<br>  - 해당 품목의 제조·수입기록서 사본<br>  - 판매처별 판매량·판매일 등의 기록<br>  - 회수 사유를 적은 서류 |\n해설: 위해화장품 회수 시 제출하는 회수계획서 및 관련 서류에는 회수 사유를 적은 서류 등이 포함되지만, '타사 제품과의 원가 비교 분석표'는 포함 항목에 해당하지 않으므로 ①번이 정답입니다. 나머지 선지의 회수 사유 및 제품·회수 관련 정보 등은 회수 계획에 필요한 항목이나, 타사와의 원가 비교는 회수 계획과 무관합니다.",
