  "derivedFrom": "subject2_q118#3",
  "explain": "📖 법령 근거 (L411):\n② 국제규격인증업체(CGMP, ISO9000) 또는 품질보증 능력이 있다고 인정되는 업체에서 제공된 원료ㆍ자재는 제공된 적합성에 대한 기록의 증거를 고려하여 검사의 방법과 시험항목을 조정할 수 있다.\n해설: 완제품은 품질보증(QA) 부서의 시험 검사를 거쳐 최종 적합 승인 및 출하 판정 라벨이 부착된 제품에 한하여 정식 절차를 거쳐 출고해야 하므로 ②번이 옳습니다. 시험 검사를 생략하거나 검사 중 또는 부적합 판정을 받은 제품을 임의 요청, 재작업 예정, 대표이사 지시 등을 이유로 사전 출하하는 것은 불가능하므로 ①, ③, ④, ⑤번은 틀렸습니다.",
