  "sid": "manufacturing_st_bd8cd5",
  "derivedFrom": "subject2_q199#1",
  "explain": "📖 교재 근거 (L2408):\n#### 1.7 천연화장품·유기농화장품의 용기와 포장 `🎯 기출`\n천연화장품·유기농화장품의 용기와 포장에는 폴리염화비닐(PVC: Polyvinyl Chlorid)과 폴리스티렌폼(Polystyrene Foam)을 사용할 수 없다.\n해설: 천연화장품 및 유기농화장품의 용기와 포장에는 폴리염화비닐(PVC)과 폴리스티렌폼을 사용할 수 없으므로 정답은 ③입니다. 따라서 사용할 수 없는 재질로 명시되지 않은 유리, 폴리에틸렌(PE), 알루미늄, 종이를 제시한 ①, ②, ④, ⑤는 오답입니다.",
