  "derivedFrom": "subject2_q209#1",
  "explain": "📖 교재 근거 (L2939):\n| 알파-하이드록시애씨드(AHA) 함유 제품 🎯 기출 | • 햇빛에 대한 피부의 감수성을 증가시킬 수 있으므로 자외선 차단제를 함께 사용할 것(씻어내는 제품 및 두발용 제품은 제외) • 일부에 시험 사용하여 피부 이상을 확인할 것 • 고농도의 AHA는 부작용 발생 우려가 있으므로 전문의 등에게 상담할 것(AHA 성분이 10% 초과하여 함유되어 있거나 산도가 3.5 미만인 제품만 표시함) |\n> 해설: \"3세 이하 영유아에게는 사용하지 말 것\"은 살리실릭애씨드 및 IPBC 함유 제품의 주의사항이다.",
