  "explain": "📖 교재 근거:\n> ② 50 이상의 제품은 SPF 50+로 표시한다\n해설: 자외선 차단지수 50 이상의 제품은 SPF 50+로 표시한다. SPF는 UVB 차단 지수이며 SPF 1은 약 10~15분의 차단 효과를 나타내고, SPF 10 이하 제품은 효능·효과를 기재할 수 없다.",
