  "truth": true,
  "mode": "fact",
  "sid": "manufacturing_st_1f2143",
  "derivedFrom": "subject2_q295#5",
  "explain": "📖 교재 근거:\n| 미셀 | 계면활성제가 수용액에서 형성하는 구형 집합체. 친수기 바깥, 소수기 안쪽. 가용화의 기본 구조. |\n해설: 계면활성제가 수용액에서 형성하는 구형 집합체인 미셀은 친수기가 바깥쪽, 소수기(친유기)가 안쪽을 향하는 구조를 가진다.",
