  "sid": "manufacturing_st_03c81e",
  "derivedFrom": "subject2_q304#1",
  "explain": "📖 교재 근거:\n| AHA | 알파하이드록시산(Alpha Hydroxy Acid). 화학적 각질 제거. 글리콜산(분자량 최소), 젖산, 사과산, 구연산, 타르타르산. 10% 초과·pH 3.5 미만 시 주의사항 표시. |\n해설: AHA(알파하이드록시산)는 자외선 차단 성분이 아니라 화학적 각질 제거 성분이다. 글리콜산(분자량 최소), 젖산, 사과산 등이 이에 속하며 10% 초과 또는 pH 3.5 미만 시 주의사항을 표시해야 한다.",
